// Old C++98/03 way with nested typedef
template<typename T>
struct MyVector {
  typedef T* Ptr; // Nested typedef
};

template<typename T>
void process_ptr(typename MyVector<T>::Ptr p) { /* ... */ }

// Modern C++11 way with alias templates
template<typename T>
using MyVectorPtr = T*;

template<typename T>
void process_ptr_modern(MyVectorPtr<T> p) { /* ... */ }

// Using alias templates for type traits (C++14 style)
#include <type_traits>
#include <vector>

std::remove_const_t<const int> i = 10; // i is 'int'
std::add_lvalue_reference_t<int> j = i; // j is 'int&'
